CREATE TABLE IF NOT EXISTS solazeroth_v3_faux_indicateurs (entry INT UNSIGNED NOT NULL PRIMARY KEY);
INSERT IGNORE INTO solazeroth_v3_faux_indicateurs SELECT DISTINCT t.entry FROM creature c JOIN creature_template t ON t.entry = c.id WHERE (c.zoneId IN (14, 1637) OR c.map = 389) AND (t.npcflag & 2) AND NOT EXISTS (SELECT 1 FROM creature_queststarter q WHERE q.id = t.entry) AND NOT EXISTS (SELECT 1 FROM creature_questender q WHERE q.id = t.entry);
UPDATE creature_template t JOIN solazeroth_v3_faux_indicateurs f ON f.entry = t.entry SET t.npcflag = t.npcflag & ~2;
